<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Support\Facades\File;
final class LogController extends Controller{
 public function access(Request $r){$rows=DB::table('access_logs')->when($r->filled('event'),fn($q)=>$q->where('event',$r->input('event')))->when($r->filled('successful'),fn($q)=>$q->where('successful',$r->boolean('successful')))->orderByDesc('id')->paginate(50)->withQueryString();return view('admin.logs.access',compact('rows'));}
 public function activity(Request $r){$rows=DB::table('activity_logs')->when($r->filled('q'),fn($q)=>$q->where(fn($q)=>$q->where('action','like','%'.$r->string('q').'%')->orWhere('route','like','%'.$r->string('q').'%')))->orderByDesc('id')->paginate(50)->withQueryString();return view('admin.logs.activity',compact('rows'));}
 public function error(Request $r){$files=collect(File::glob(storage_path('logs/*.log')))->map(fn($p)=>['name'=>basename($p),'size'=>File::size($p),'modified'=>File::lastModified($p)])->sortByDesc('modified')->values();$selected=basename((string)$r->input('file',''));$content='';if($selected&&$files->contains('name',$selected)){$path=storage_path('logs/'.$selected);$size=File::size($path);$handle=fopen($path,'rb');if($size>524288)fseek($handle,-524288,SEEK_END);$content=stream_get_contents($handle)?:'';fclose($handle);$content=preg_replace('/(password|token|secret|api[_-]?key|authorization)(["\'\s:=]+)[^\s,}\]]+/i','$1$2[REDACTED]',$content)??'';}return view('admin.logs.error',compact('files','selected','content'));}
}
